import pandas as pd, numpy as np, os
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
base='../persistent/stock_data'
# Overnight gap reversal: negative open-to-prior-close gap, known at prior close? open is not known at decision;
# used strictly as completed-day signal for next day, so valid research but operationally requires open.
xs=[]
for s in U:
 d=pd.read_csv(os.path.join(base,s+'.csv'),parse_dates=['date']).sort_values('date')
 d['gap']=d['open']/d['close'].shift(1)-1
 d['fwd']=d['close'].shift(-1)/d['close']-1
 d['signal']=-d['gap']
 xs.append(d[['date','signal','fwd']].assign(symbol=s))
z=pd.concat(xs).dropna()
ics=[]; rows=[]
for dt,g in z.groupby('date'):
 if len(g)>=8:
  ic=spearmanr(g.signal,g.fwd).statistic
  if np.isfinite(ic): ics.append(ic); rows.append((dt,ic,len(g)))
a=np.array(ics)
print('dates',len(a),'rows',len(z),'avg_names',np.mean([x[2] for x in rows]),'coverage',len(z)/(len(U)*len(set(z.date))))
print('IC %.8f ICIR %.8f hit %.4f'%(a.mean(),a.mean()/a.std(ddof=1),np.mean(a>0)))
for label,cond in [('2020-2024',lambda d:d<'2025-01-01'),('2025-2026',lambda d:(d>='2025-01-01')&(d<'2027-01-01')),('2027',lambda d:d>='2027-01-01')]:
 q=np.array([ic for dt,ic,n in rows if cond(dt)])
 print(label,len(q), 'IC %.6f ICIR %.6f hit %.3f'%(q.mean(),q.mean()/q.std(ddof=1),np.mean(q>0)) if len(q)>1 else '')
for h in [2,5,10]:
 vals=[]
 for s in U:
  d=pd.read_csv(os.path.join(base,s+'.csv'),parse_dates=['date']).sort_values('date'); d['signal']=- (d.open/d.close.shift(1)-1); d['fwdh']=d.close.shift(-h)/d.close-1; vals.append(d[['date','signal','fwdh']])
 q=pd.concat(vals).dropna(); ii=[]
 for dt,g in q.groupby('date'):
  if len(g)>=8: ii.append(spearmanr(g.signal,g.fwdh).statistic)
 ii=np.array(ii); print('horizon',h,'IC %.6f ICIR %.6f'%(np.nanmean(ii),np.nanmean(ii)/np.nanstd(ii,ddof=1)))

