import pandas as pd,numpy as np
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']; END=pd.Timestamp('2028-07-11')
P={}
for s in U:
 x=pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']); P[s]=x[x.date<=END].set_index('date').close.sort_index()
px=pd.DataFrame(P).sort_index(); r=px.pct_change(); vol=r.rolling(20).std(); ret5=px/px.shift(5)-1
# volatility-scaled short-term reversal, activated during broad weakness; otherwise mild reversal
breadth=(ret5>0).mean(axis=1)
stress=(breadth<0.45).astype(float)
sig=-(ret5/vol).mul(0.5+stress,axis=0).replace([np.inf,-np.inf],np.nan).shift(1)
rows=[]
for d in px.index:
 g=pd.DataFrame({'s':sig.loc[d],'f':(px.shift(-1)/px-1).loc[d]}).dropna()
 if len(g)>=8 and g.s.nunique()>1 and g.f.nunique()>1: rows.append((d,spearmanr(g.s,g.f).statistic,len(g)))
z=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date')
print('candidate=stress-conditioned volatility-scaled 5d reversal');print('dates',len(z),'rows',int(z.n.sum()),'avgN',round(z.n.mean(),2),'coverage',round(sig.notna().sum().sum()/sig.size,4));print('IC %.6f ICIR %.6f hit %.4f'%(z.ic.mean(),z.ic.mean()/z.ic.std(ddof=1),(z.ic>0).mean()))
