import pandas as pd,numpy as np
from scipy.stats import spearmanr
A=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P=pd.concat({a:pd.read_csv('../persistent/stock_data/'+a+'.csv',parse_dates=['date']).set_index('date')['close'] for a in A},axis=1).sort_index().loc[:'2029-09-05']; r=P.pct_change()
# lagged volatility-scaled 20d reversal, broad coverage
vol=r.rolling(60,min_periods=40).std(); factor=(-r.rolling(20,min_periods=20).sum()/vol.replace(0,np.nan)).shift(1)
rows=[]
for d in P.index:
 z=pd.concat([factor.loc[d],(P.shift(-10)/P-1).loc[d]],axis=1).dropna()
 if len(z)>=8: rows.append((d,spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic,len(z)))
R=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date'); print('period',R.index.min(),R.index.max(),'obs',len(R),'avg_n',round(R.n.mean(),2),'coverage',round(R.n.sum()/(len(R)*15),4))
for nm,q in [('full',slice(None)),('2026',slice('2026','2026')),('2027-28',slice('2027','2028')),('recent360',slice('2028-09-05','2029-09-05')),('recent180',slice('2029-03-01','2029-09-05'))]:
 x=R.loc[q,'ic']; print(nm,len(x),round(x.mean(),6),round(x.mean()/x.std(ddof=1),6),round((x>0).mean(),4))
for h in [1,5,10,20]:
 fw=P.shift(-h)/P-1; vals=[]
 for d in P.index:
  z=pd.concat([factor.loc[d],fw.loc[d]],axis=1).dropna()
  if len(z)>=8: vals.append(spearmanr(z.iloc[:,0],z.iloc[:,1]).statistic)
 x=pd.Series(vals); print('decay',h,len(x),round(x.mean(),6),round(x.mean()/x.std(ddof=1),6))
print('turnover',round(factor.rank(axis=1,pct=True).diff().abs().mean(axis=1).dropna().mean(),6)); factor.reset_index().melt(id_vars='date',var_name='symbol',value_name='signal').dropna().to_csv('scripts/miner_1_20290906_vol_scaled_reversal_signal.csv',index=False)

import numpy as np,pandas as pd
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
D={s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).sort_values('date').set_index('date') for s in U}
# Candidate: drawdown recovery, activated only when lagged cross-asset breadth is weak (<= median); lagged and volatility normalized.
allr=[]
for s,x in D.items():
 p=x.close.astype(float); allr.append(p.pct_change(20).rename(s))
R=pd.concat(allr,axis=1); breadth=(R>0).mean(axis=1).shift(1); threshold=breadth.rolling(252,min_periods=100).median().shift(1)
rows=[]
for s,x in D.items():
 p=x.close.astype(float); r=p.pct_change(); trough=p.rolling(60,min_periods=40).min(); vol=r.rolling(20,min_periods=15).std()
 base=np.log(p/trough)/vol.replace(0,np.nan)
 f=base.where(breadth<=threshold).shift(1); fw=np.log(p.shift(-10)/p.shift(-1))
 rows.append(pd.DataFrame({'date':p.index,'symbol':s,'factor':f,'fwd':fw}))
a=pd.concat(rows).dropna(); a=a[a.date<=pd.Timestamp('2029-09-18')]
ics=[]
for dt,g in a.groupby('date'):
 if len(g)>=8 and g.factor.nunique()>1 and g.fwd.nunique()>1: ics.append(g.factor.corr(g.fwd,method='spearman'))
ic=pd.Series(ics).dropna(); print('dates',len(ic),'avg_instruments',round(a.groupby('date').size().loc[a.groupby('date').size()>=8].mean(),2),'coverage',round(len(a)/(len(a.date.unique())*15),4)); print('IC',round(ic.mean(),6),'ICIR',round(ic.mean()/ic.std(),6),'hit',round((ic>0).mean(),4))
for h in [1,5,10,20]:
 q=[]
 for s,x in D.items():
  p=x.close.astype(float); r=p.pct_change(); tr=p.rolling(60,min_periods=40).min(); v=r.rolling(20,min_periods=15).std(); f=(np.log(p/tr)/v.replace(0,np.nan)).where(breadth<=threshold).shift(1); fw=np.log(p.shift(-h)/p.shift(-1)); q.append(pd.DataFrame({'date':p.index,'f':f,'y':fw}))
 z=pd.concat(q).dropna(); vals=[]
 for dt,g in z.groupby('date'):
  if len(g)>=8 and g.f.nunique()>1 and g.y.nunique()>1: vals.append(g.f.corr(g.y,method='spearman'))
 ss=pd.Series(vals).dropna(); print('h',h,'IC',round(ss.mean(),6),'ICIR',round(ss.mean()/ss.std(),6),'n',len(ss))
print('regimes')
# recompute dated IC
icd=[]
for dt,g in a.groupby('date'):
 if len(g)>=8 and g.factor.nunique()>1 and g.fwd.nunique()>1: icd.append((dt,g.factor.corr(g.fwd,method='spearman')))
s=pd.Series(dict(icd));
for n,m in [('2026',s.index.year==2026),('2027-28',s.index.year.isin([2027,2028])),('recent360',s.index>=s.index.max()-pd.Timedelta(days=360)),('recent180',s.index>=s.index.max()-pd.Timedelta(days=180))]:
 q=s[m].dropna(); print(n,len(q),round(q.mean(),6),round(q.mean()/q.std(),6) if q.std()>0 else None)
print('turnover',round(float(a.pivot(index='date',columns='symbol',values='factor').rank(pct=True).diff().abs().mean().mean()),6))

import os,numpy as np,pandas as pd
from scipy.stats import spearmanr
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
P=pd.DataFrame({s:pd.read_csv('../persistent/stock_data/'+s+'.csv',parse_dates=['date']).set_index('date')['close'].astype(float) for s in U}).sort_index().loc[:'2029-10-03']; r=P.pct_change()
# downside-asymmetry reversal: prior 10d return, normalized by downside deviation over prior 30d
neg=r.clip(upper=0); dd=neg.rolling(30,min_periods=15).std()*np.sqrt(30)
sig=(-P.pct_change(10)/dd).shift(1)
def ev(h):
 f=P.shift(-h)/P-1; z=[]
 for d in sig.index:
  q=pd.concat([sig.loc[d],f.loc[d]],axis=1).dropna()
  if len(q)>=8:z.append((d,len(q),spearmanr(q.iloc[:,0],q.iloc[:,1]).statistic))
 return pd.DataFrame(z,columns=['date','n','ic']).set_index('date')
q=ev(10);print('period',q.index.min().date(),q.index.max().date(),'dates',len(q),'avg_n',q.n.mean(),'coverage',q.n.sum()/(len(q)*15));print('IC',q.ic.mean(),'ICIR',q.ic.mean()/q.ic.std(ddof=1),'hit',(q.ic>0).mean(),'turnover',sig.rank(axis=1,pct=True).diff().abs().mean(axis=1).mean())
for name,s in [('2026',q.loc['2026']),('2027-28',q.loc['2027':'2028']),('recent360',q.tail(360)),('recent180',q.tail(180))]:print(name,len(s),s.ic.mean(),s.ic.mean()/s.ic.std(ddof=1))
for h in [1,5,10,20]:
 a=ev(h).ic.to_numpy();print('decay',h,np.mean(a),np.mean(a)/np.std(a,ddof=1),len(a))
sig.stack().rename('signal').rename_axis(['date','symbol']).reset_index().to_csv('scripts/miner_1_20291004_downside_reversal_signal.csv',index=False)

