 d=None
 try:d=get_index_daily_data(s,3000)
 except:pass
 if d is None:
  try:d=get_stock_daily_data(s,3000)
  except:pass
 if d is not None and len(d)>100:raw[s]=d[['date','close']].set_index('date')
idx=sorted(set.intersection(*[set(x.index) for x in raw.values()]))
P=pd.DataFrame({s:raw[s].reindex(idx).close for s in raw}).sort_index(); r=P.pct_change()
# Tail-asymmetry reversal: assets with unusually negative downside-tail share
# are favored (contrarian), normalized by total risk; all inputs lagged one day.
down=r.where(r<0,0).rolling(20).apply(lambda x: np.mean(x<0)*np.mean(np.abs(x[x<0])) if np.any(x<0) else np.nan,raw=False).shift(1)
tot=r.abs().rolling(20).mean().shift(1)
asym=(down/tot).replace([np.inf,-np.inf],np.nan)
# cross-sectional centered tail signal, with magnitude preserved
f=-(asym-asym.median(axis=1).values[:,None])
fw=P.shift(-10)/P-1
rows=[]; ranks=[]
for dt in P.index:
 a,b=f.loc[dt],fw.loc[dt];ok=a.notna()&b.notna()
 if ok.sum()>=8:rows.append((dt,a[ok].corr(b[ok],method='spearman'),ok.sum()));ranks.append(a.rank(pct=True))
q=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date'); sr=pd.DataFrame(ranks,index=q.index)
for lab,z in [('all',q),('r365',q.tail(365)),('r180',q.tail(180)),('r60',q.tail(60))]:
 m=z.ic.mean();sd=z.ic.std(ddof=1);print(lab,len(z),round(z.n.mean(),2),round(m,6),round(m/sd,6),round((z.ic>0).mean(),4))
print('coverage',round(sum(q.n)/(len(q)*15),4),'turnover',round(float(sr.diff().abs().mean().mean()),6),'assets',len(raw),'period',q.index.min(),q.index.max())
f.to_csv('scripts/miner_1_20310904_tail_asymmetry_reversal_signal.csv');q.to_csv('scripts/miner_1_20310904_tail_asymmetry_reversal_ic.csv')
for h in [1,5,10,20]:
 rr=[];fw=P.shift(-h)/P-1
 for dt in P.index:
  a,b=f.loc[dt],fw.loc[dt];ok=a.notna()&b.notna()
  if ok.sum()>=8:rr.append(a[ok].corr(b[ok],method='spearman'))
 print('decay',h,len(rr),round(np.nanmean(rr),6))

