    if d is None or len(d)<300:
        try: d=get_stock_daily_data(s,3200)
        except Exception: d=None
    if d is not None and len(d)>300:
        x=d.copy(); x.date=pd.to_datetime(x.date)
        px[s]=x.set_index('date').close.astype(float)
P=pd.DataFrame(px).sort_index().ffill()
r=np.log(P).diff()
# Lag-safe 20d risk-adjusted momentum, attenuated in high-VIX regimes.
base=P.shift(1).pct_change(20)/(r.shift(1).rolling(20).std()*np.sqrt(252)+1e-12)
v=pd.read_csv('../persistent/index_data/VIX.csv')
v['date']=pd.to_datetime(v['date'])
vc=v.set_index('date')['close'].astype(float).reindex(P.index).ffill()
vix_pct=vc.shift(1).rolling(252,min_periods=60).rank(pct=True)
# Smooth regime weight: 1 in calm, 0.25 in extreme stress, preserving cross-sectional ordering.
reg=(1.0-0.75*vix_pct.clip(0,1)).fillna(1.0)
f=base.mul(reg,axis=0)
fwd=P.shift(-10)/P-1
rows=[]
for dt in f.index:
 a=f.loc[dt]; b=fwd.loc[dt]; ok=a.notna()&b.notna()
 if ok.sum()>=8: rows.append((dt,a[ok].rank().corr(b[ok].rank()),ok.sum()))
z=pd.DataFrame(rows,columns=['date','ic','n']).set_index('date').dropna()
for name,x in [('full',z),('recent365',z.tail(365)),('recent180',z.tail(180)),('recent60',z.tail(60)),('2029',z.loc['2029']),('2030',z.loc['2030']),('2031',z.loc['2031']),('2032',z.loc['2032'])]:
