rv=lr.rolling(20,min_periods=15).std(); trend=np.log(p/p.shift(20))/rv; vr=(vix/vix.rolling(120,min_periods=60).median()).clip(.5,2); reg=(1.5-vr).clip(-.5,1.0)
# Contrarian counterpart: inverse of volatility-adjusted intermediate trend, gated by the lagged VIX regime.
r=trend.mul(reg,axis=0).rank(axis=1,pct=True); f=(-r).sub((-r).mean(axis=1),axis=0).rolling(2,min_periods=2).mean()
