p=pd.DataFrame(D).sort_index().ffill(); r=p.pct_change()
# Candidate: intermediate momentum scaled by idiosyncratic risk, retained only when
# the asset's recent volatility is below the cross-sectional median. All inputs lagged.
ret20=p.pct_change(20); vol20=r.rolling(20,min_periods=15).std(); vol60=r.rolling(60,min_periods=40).std()
lowvol=(vol20.lt(vol20.median(axis=1),axis=0)).astype(float)
sig=(ret20/(vol20.replace(0,np.nan)*np.sqrt(252))).where(lowvol>0).shift(1)
# forward returns beginning after signal date
fwd={h:p.shift(-h)/p-1 for h in [1,5,10,20]}
def calc(x):
 vals=[]; ns=[]
 for dt in sig.index:
  z=pd.concat([sig.loc[dt],x.loc[dt]],axis=1).dropna()
  if len(z)>=8: vals.append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); ns.append(len(z))
 return pd.Series(vals), (np.mean(ns) if ns else np.nan)
v,n=calc(fwd[10]); print('dates',len(v),'avgN',round(n,3),'coverage',round(sig.notna().mean().mean(),5),'IC',round(v.mean(),6),'ICIR',round(v.mean()/v.std(ddof=1),6),'hit',round((v>0).mean(),5))
for h in [1,5,10,20]:
