 if len(z)>=8: ts.append((z.iloc[:,1]-z.iloc[:,0]).abs().mean())
print('turnover',round(np.mean(ts),6),'signal_dates',sig.notna().any(axis=1).sum())
out=sig.stack().rename('signal').reset_index(); out.columns=['date','symbol','signal']; out.to_csv('scripts/miner_1_20350104_volatility_gated_momentum_signal.csv',index=False)

